WITH base AS (SELECT id, supplier_name, country, city, rating, CEIL(rating) AS rating_whole FROM suppliers WHERE city IS NOT DISTINCT FROM 'Berlin') SELECT city, CASE WHEN rating_whole >= 70 THEN 'HIGH' ELSE 'LOW' END AS rating_whole_tier, COUNT_IF(city = 'Chiang Mai') AS chiang_mai_events, COUNT(*) AS cnt FROM base GROUP BY city, CASE WHEN rating_whole >= 70 THEN 'HIGH' ELSE 'LOW' END ORDER BY chiang_mai_events DESC
